-- =====================================================================
-- Rens Dynamics ERP — 10 Demo Records Seeding Script
-- Database: u745362362_renserp
-- Modules Included:
--   1. Customers (10 Master Customer Records)
--   2. Fleet Personnel / Drivers & Crew (10 Records)
--   3. Fleet Vehicles / Lorries (10 Records)
--   4. Lorry Crew Assignments (10 Records)
--   5. Commercial Quotations & Contracts (10 Records)
--   6. Staff Admin Accounts
-- =====================================================================

USE `u745362362_renserp`;
SET FOREIGN_KEY_CHECKS = 0;

-- ── 1. Staff Accounts ─────────────────────────────────────────────────
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `pin`=VALUES(`pin`);

-- ── 2. Customers (10 Demo Records) ───────────────────────────────────
ON DUPLICATE KEY UPDATE `company_name`=VALUES(`company_name`), `phone`=VALUES(`phone`), `email`=VALUES(`email`), `default_rate`=VALUES(`default_rate`);

-- ── 3. Drivers & Crew (10 Demo Records) ───────────────────────────────
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `phone`=VALUES(`phone`), `status`=VALUES(`status`);

-- ── 4. Vehicles / Lorries (10 Demo Records) ───────────────────────────
ON DUPLICATE KEY UPDATE `capacity_desc`=VALUES(`capacity_desc`), `default_driver_id`=VALUES(`default_driver_id`), `status`=VALUES(`status`);

-- ── 5. Lorry Crew Mapping (10 Records) ────────────────────────────────
ON DUPLICATE KEY UPDATE `role`=VALUES(`role`);

-- ── 6. Quotations (10 Demo Records) ──────────────────────────────────
ON DUPLICATE KEY UPDATE `customer_name`=VALUES(`customer_name`), `rate_amount`=VALUES(`rate_amount`), `special_instructions`=VALUES(`special_instructions`), `status`=VALUES(`status`);

SET FOREIGN_KEY_CHECKS = 1;
